functions.buildSpatialIndex:
function buildSpatialIndex() {
  spatialGrid = new Map();
  corridorIndex = new Map();
  for (let i = 0; i < calibData.length; i++) {
    const p = calibData[i];
    const g = gridKey(p.lat, p.lon);
    let bucket = spatialGrid.get(g); if (!bucket) { bucket = []; spatialGrid.set(g, bucket); } bucket.push(i);
    const c = corridorKey(p.e, p.b);
    let cb = corridorIndex.get(c); if (!cb) { cb = []; corridorIndex.set(c, cb); } cb.push(i);
  }
}

functions.nearbyIndices:
function nearbyIndices(lat, lon, rings) {
  const out = []; const gx = Math.floor(lat / GRID_SIZE), gy = Math.floor(lon / GRID_SIZE);
  for (let dx = -rings; dx <= rings; dx++) for (let dy = -rings; dy <= rings; dy++) {
    const b = spatialGrid.get(`${gx + dx},${gy + dy}`); if (b) out.push(...b);
  }
  return out;
}

functions.nearestFrom:
function nearestFrom(indices, lat, lon, skipIdx = -1) {
  let bestIdx = -1, bestDist = Infinity;
  for (const i of indices) {
    if (i === skipIdx) continue;
    const p = calibData[i], d = haversineKm(lat, lon, p.lat, p.lon);
    if (d < bestDist) { bestDist = d; bestIdx = i; }
  }
  return bestIdx < 0 ? null : { idx: bestIdx, dist: bestDist };
}

functions.haversineKm:
function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

functions.computeKmStation:
function computeKmStation(lat, lon, expressway = '') {
  if (calibData.length < 1) return null;
  let candidates = nearbyIndices(lat, lon, 4);
  if (expressway) candidates = candidates.filter(i => calibData[i].e === expressway);
  if (!candidates.length) {
    candidates = calibData.map((point, index) => (!expressway || point.e === expressway) ? index : -1).filter(index => index >= 0);
  }

  let first = nearestFrom(candidates, lat, lon);
  if (!first) return null;
  const best = calibData[first.idx];

  // If the local grid did not contain enough points from the identified corridor,
  // fall back to the corridor index (still much smaller than the whole dataset).
  let same = corridorIndex.get(corridorKey(best.e, best.b)) || [];
  if (same.length < 2) same = candidates.filter(i => calibData[i].e === best.e && calibData[i].b === best.b);
  if (same.length < 2) same = calibData.map((p, i) => p.e === best.e && p.b === best.b ? i : -1).filter(i => i >= 0);

  const second = nearestFrom(same, lat, lon, first.idx);
  let km = best.k;
  if (second) {
    const total = first.dist + second.dist;
    km = total === 0 ? best.k : best.k + (calibData[second.idx].k - best.k) * (first.dist / total);
  }
  return { km, expressway: best.e, bound: best.b, distance: first.dist };
}

functions.computeCorridorCandidates:
function computeCorridorCandidates(lat, lon) {
  const local = nearbyIndices(lat, lon, 4);
  const corridors = new Set(local.map(index => calibData[index].e));
  const confirmed = locationResolver.state().confirmedCorridor;
  if (confirmed) corridors.add(confirmed);
  if (!corridors.size) for (const point of calibData) corridors.add(point.e);
  return [...corridors].map(expressway => computeKmStation(lat, lon, expressway)).filter(Boolean);
}

functions.offNetworkThresholdKm:
function offNetworkThresholdKm(accuracyMeters) {
  if (!accuracyMeters || !Number.isFinite(accuracyMeters)) return OFF_NETWORK_KM;
  const bufferKm = Math.min(accuracyMeters, 200) / 1000;
  return Math.min(OFF_NETWORK_KM + bufferKm, 0.35);
}

functions.isInterchangeLocationMode:
function isInterchangeLocationMode(resolution = currentResolvedLocation, position = currentPos) {
  return !!position && SPOTITLocation.isInterchangeMode(resolution, position.acc);
}

functions.interchangeSegmentLabel:
function interchangeSegmentLabel(resolution = currentResolvedLocation) {
  return resolution?.interchange?.segment || 'Ramp / interchange roadway';
}

functions.resolvedLocationCanSave:
function resolvedLocationCanSave() {
  if (!currentPos || !currentPos.fresh || !currentResolvedLocation?.saveAllowed) return false;
  const result = currentResolvedLocation.result;
  return !!result && (isInterchangeLocationMode() || result.distance <= offNetworkThresholdKm(currentPos.acc));
}

functions.resolvedEntrySnapshot:
function resolvedEntrySnapshot() {
  if (!resolvedLocationCanSave()) return null;
  const result = currentResolvedLocation.result;
  const interchangeMode = isInterchangeLocationMode();
  return {
    lat: currentPos.lat, lon: currentPos.lon,
    km: interchangeMode ? null : result.km,
    expressway: result.expressway,
    bound: userBound || '',
    interchange: interchangeMode ? currentResolvedLocation.interchange.name : '',
    interchangeSegment: interchangeMode ? interchangeSegmentLabel() : ''
  };
}
